export const kettles = raw.map(([number, capacity, power]) => ({ product: `제품 ${number}`, capacity, power }))

export function kettleHistogram() {
  const bins = [500, 1000, 1500, 2000, 2500, 3000]
  return bins.map((upper, index) => ({
    label: index === 0 ? `~${upper}` : `${bins[index - 1] + 1}~${upper}`,
    value: kettles.filter((item) => item.power > (index === 0 ? 0 : bins[index - 1]) && item.power <= upper).length,
    color: '#2b78d0',
  }))
}
